package org.jlinalg.cli;
import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import org.jlinalg.study.StudyCohortPolicy;
import org.jlinalg.study.StudyOperationExecutor.Context;

/** Reuse source-assessed cohort labels; local count/plot views do not rerun statistical analyses. */
final class StudySuppliedCohorts {
    private StudySuppliedCohorts() { }
    static void write(Context c,String kind,List<String> header,List<String[]> rows,Map<String,Object> definition,Map<String,Object> metadata,List<String> needs,List<String> outputs)throws IOException {
        if(kind.equals("rare_cohort_overlap")){rare(c,header,rows,definition,metadata,needs,outputs);return;}
        if(!Set.of("cohort_overlap","heterogeneity_review").contains(kind))return;
        var summary=new LinkedHashMap<String,Object>();summary.put("execution_origin","externally_produced");summary.put("analysis_executed_by_jlinalg",false);summary.put("source_method",definition.get("method"));summary.put("source_scope",definition.get("scope"));summary.put("source_testing_family",definition.getOrDefault("family",Map.of()));summary.put("source_result_sha256",metadata.get("canonical_sha256"));summary.put("local_work","Typed validation and count/plot views; source selection and heterogeneity tests were not rerun");
        if(kind.equals("cohort_overlap")){
            var ids=new TreeSet<String>();for(String[] row:rows)ids.add(row[header.indexOf("set_id")]);var selected=new TreeMap<String,Set<String>>();for(String id:ids)selected.put(id,new TreeSet<>());var features=new TreeMap<String,Map<String,String[]>>();for(String[] row:rows)features.computeIfAbsent(row[header.indexOf("feature_id")],key->new TreeMap<>()).put(row[header.indexOf("set_id")],row);
            boolean complete=features.values().stream().allMatch(values->values.keySet().equals(ids));if(!complete){needs.add("Supplied cohort membership must include an explicit observed/unobserved row for every feature and set; missing rows cannot become negative evidence");summary.put("assessment_complete",false);}
            var patterns=new TreeMap<String,long[]>();long[] degrees=new long[ids.size()+1];int universe=0;var featureRows=new ArrayList<String[]>();
            for(var entry:features.entrySet()){
                Boolean included=null;for(String[] row:entry.getValue().values()){boolean flag=truth(row,header,"in_universe");if(included!=null&&flag!=included)throw new IOException("Supplied overlap universe membership differs between sets for one feature");included=flag;}
                if(!Boolean.TRUE.equals(included))continue;universe++;StringBuilder signature=new StringBuilder();int tested=0,count=0;for(String id:ids){String[] row=entry.getValue().get(id);boolean hit=row!=null&&truth(row,header,"selected");if(row!=null&&truth(row,header,"source_estimable"))tested++;if(hit){count++;selected.get(id).add(entry.getKey());}signature.append(row==null?'?':hit?'1':'0');}degrees[count]++;long[] totals=patterns.computeIfAbsent(signature.toString(),ignored->new long[2]);totals[0]++;if(tested==ids.size())totals[1]++;featureRows.add(new String[]{entry.getKey(),signature.toString(),String.valueOf(tested),String.valueOf(count),"Source-assessed selection labels; no FDR or direction criterion was recomputed"});
            }
            var patternRows=new ArrayList<String[]>();for(var entry:patterns.entrySet())patternRows.add(new String[]{entry.getKey(),String.valueOf(entry.getValue()[0]),String.valueOf(entry.getValue()[1]),String.valueOf(entry.getValue()[0]-entry.getValue()[1])});FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-patterns.tsv"),List.of("selected_pattern","features","all_sets_estimable","partial_coverage_features"),patternRows);outputs.add("cohort-overlap-patterns.tsv");FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-features.tsv"),List.of("feature_id","selected_pattern","estimable_sets","selected_sets","interpretation"),featureRows);outputs.add("cohort-overlap-features.tsv");var degreeRows=new ArrayList<String[]>();for(int i=0;i<degrees.length;i++){long atLeast=0;for(int j=i;j<degrees.length;j++)atLeast+=degrees[j];degreeRows.add(new String[]{String.valueOf(i),String.valueOf(degrees[i]),String.valueOf(atLeast),String.valueOf(universe)});}FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-degree.tsv"),List.of("selected_sets","exact_features","at_least_features","universe_features"),degreeRows);outputs.add("cohort-overlap-degree.tsv");
            summary.put("set_order",List.copyOf(ids));summary.put("universe_features",universe);summary.put("selected_union_features",universe-degrees[0]);summary.put("all_sets_selected_features",degrees[ids.size()]);summary.put("observed_patterns",patterns.size());summary.put("selection_origin","source_assessed_labels_not_recomputed");summary.put("alert_assessment_complete",false);summary.put("zero_overlap_alerts",List.of());summary.put("zero_overlap_alert_status","Source significance labels retained; cohort/family alert applicability requires the source's explicit reviewed rule");summary.put("required_manuscript_caveat",StudyCohortOverlap.CAVEAT+" Supplied membership selection, tested coverage and direction are source declarations.");
            var p=StudyCohortPolicy.overlap(map(StudyResultTables.analysis(c).get("cohort_overlap")));if(complete&&ids.size()>=2&&ids.size()<=((Number)p.get("maximum_sets")).intValue()){
                StudyCohortOverlap.plot(c,p,List.copyOf(ids),selected,patterns,summary);try(var paths=java.nio.file.Files.list(c.outputDirectory())){for(var file:paths.filter(path->path.getFileName().toString().startsWith("cohort-overlap-")&&(path.toString().endsWith(".png")||path.toString().endsWith(".pdf"))).toList())outputs.add(file.getFileName().toString());}
            }else if(complete)summary.put("plot_disposition","Source set count is outside native display bounds; no source sets or membership rows were dropped");
            summary.put("assessment_complete",complete);StudyPublicEvidence.write(c.outputDirectory().resolve("cohort-overlap.yaml"),summary);outputs.add("cohort-overlap.yaml");
        }else{
            var rawRule=map(map(map(definition.get("method")).get("parameters")).get("alert_rule"));boolean hasRule=rawRule.keySet().containsAll(Set.of("metric","minimum_sources","feature_scope","minimum_features","minimum_high_features","widespread_fraction","fraction_comparison"));Map<String,Object> rule=hasRule?StudyCohortPolicy.heterogeneity(rawRule):Map.of();var metrics=new TreeSet<String>();int scope=0,high=0;for(String[] row:rows){String metric=row[header.indexOf("metric")];metrics.add(metric);if(!Set.of("i_squared","q_p_value").contains(metric))throw new IOException("Supplied heterogeneity metric must be i_squared or q_p_value");boolean included=truth(row,header,"in_alert_scope");if(!included)continue;scope++;double value=Double.parseDouble(row[header.indexOf("metric_value")]);if(!Double.isFinite(value)||value<0||value>(metric.equals("i_squared")?100:1))throw new IOException("Supplied heterogeneity metric outside its scale");boolean flag=truth(row,header,"high_heterogeneity");if(flag)high++;if(hasRule){if(!metric.equals(rule.get("metric")))throw new IOException("Supplied heterogeneity metric differs from its source alert rule");boolean expected=metric.equals("i_squared")?value>=((Number)rule.get("i_squared_threshold")).doubleValue():value<((Number)rule.get("q_alpha")).doubleValue();if(flag!=expected)throw new IOException("Supplied high-heterogeneity flag disagrees with its source metric/cutoff");}}
            var family=map(definition.get("family"));boolean sourceComplete="complete".equals(family.get("coverage"))&&family.get("tested_count") instanceof Number n&&n.longValue()<=rows.size();boolean complete=hasRule&&sourceComplete&&metrics.size()==1;double fraction=scope==0?Double.NaN:high/(double)scope;boolean alert=complete&&scope>=((Number)rule.get("minimum_features")).intValue()&&high>=((Number)rule.get("minimum_high_features")).intValue()&&(rule.get("fraction_comparison").equals("greater_than")?fraction>((Number)rule.get("widespread_fraction")).doubleValue():fraction>=((Number)rule.get("widespread_fraction")).doubleValue());summary.put("assessment_complete",complete);summary.put("source_family_complete",sourceComplete);summary.put("source_alert_rule",rule);summary.put("metric",metrics.size()==1?metrics.first():"mixed_source_metrics");summary.put("scope_features",scope);summary.put("observed_high_features",high);summary.put("high_features",complete?high:"NA");summary.put("high_fraction",complete?StudyCohortResults.finite(fraction):"NA");summary.put("widespread_alert",complete?alert:"unavailable");summary.put("alert_disposition",complete?alert?"source_registered_widespread_threshold_met":"source_registered_widespread_threshold_not_met":"source_rule_or_complete_family_unavailable_not_a_negative_result");summary.put("required_manuscript_caveat",StudyHeterogeneity.CAVEAT+" Source metric adjustment, source-count eligibility and alert scope are declarations; import does not reproduce their original statistical calculation.");StudyPublicEvidence.write(c.outputDirectory().resolve("heterogeneity-review.yaml"),summary);outputs.add("heterogeneity-review.yaml");
        }
    }
    private static void rare(Context c,List<String> header,List<String[]> rows,Map<String,Object> definition,Map<String,Object> metadata,List<String> needs,List<String> outputs)throws IOException {
        var declared=new TreeSet<>(list(map(definition.get("scope")).get("datasets")).stream().map(StudyPublicEvidence::text).toList());var observed=new TreeSet<String>();for(String[] row:rows)observed.add(row[header.indexOf("set_id")]);
        if(declared.size()<2||!declared.equals(observed)){String reason="Supplied rare membership requires scope.datasets to declare the complete set order and every declared dataset must occur; an entirely absent cohort cannot silently reduce the analysis";needs.add(reason);StudyPublicEvidence.write(c.outputDirectory().resolve("cohort-overlap.yaml"),Map.of("assessment_complete",false,"alert_assessment_complete",false,"counting_unit","set_mask_prespecified_test","declared_datasets",List.copyOf(declared),"observed_datasets",List.copyOf(observed),"interpretation",reason,"required_manuscript_caveat",StudyRareCohortOverlap.CAVEAT));outputs.add("cohort-overlap.yaml");return;}
        var identities=new TreeMap<String,StudyRareCohortOverlap.Key>();var projected=new ArrayList<String[]>();
        for(String[] source:rows){var key=StudyRareCohortOverlap.key(source[header.indexOf("feature_id")],source[header.indexOf("mask_id")],source[header.indexOf("test")]);identities.put(key.id(),key);String[] row=source.clone();row[header.indexOf("feature_id")]=key.id();projected.add(row);}
        write(c,"cohort_overlap",header,projected,definition,metadata,needs,outputs);
        var file=c.outputDirectory().resolve("cohort-overlap-features.tsv");if(java.nio.file.Files.isRegularFile(file)){var table=DelimitedData.readResult(file);var fields=new ArrayList<>(table.header());fields.addAll(List.of("mask_id","test","overlap_id"));var result=new ArrayList<String[]>();for(String[] source:table.rows()){var key=identities.get(source[table.column("feature_id")]);String[] row=java.util.Arrays.copyOf(source,fields.size());row[table.column("feature_id")]=key.feature();row[fields.indexOf("mask_id")]=key.mask();row[fields.indexOf("test")]=key.test();row[fields.indexOf("overlap_id")]=key.id();result.add(row);}FollowupSupport.table(file,fields,result);}
        var summaryFile=c.outputDirectory().resolve("cohort-overlap.yaml");var summary=StudyYaml.loadArtifact(summaryFile);summary.put("counting_unit","set_mask_prespecified_test");summary.put("required_manuscript_caveat",StudyRareCohortOverlap.CAVEAT+" Supplied membership and selection are source-assessed labels; source FDR, direction, masks, scope and completeness were not independently reproduced.");StudyPublicEvidence.write(summaryFile,summary);metadata.put("required_manuscript_caveat",summary.get("required_manuscript_caveat"));
    }
    private static boolean truth(String[] row,List<String> header,String name){return row[header.indexOf(name)].equals("true");}
}
